bool process_record_user(uint16_t keycode, keyrecord_t *record) {
    if (record->event.pressed) {
        oled_timer = timer_read();
        if (!is_oled_on()) {
            oled_on();
        }
        tap_toggle = !tap_toggle;
        !tap_toggle ? draw_l() : draw_r();
    }
    return true;
}

// https://github.com/drcforbin/keyboards/blob/master/crkbd/oled.c
void render_mod_status(uint8_t modifiers) {
    oled_write_char('G', (modifiers & MOD_MASK_GUI));
    oled_write_char('A', (modifiers & MOD_MASK_ALT));
    oled_write_char('C', (modifiers & MOD_MASK_CTRL));
    oled_write_char('S', (modifiers & MOD_MASK_SHIFT));
}

void oled_task_user(void) {
    if (oled_timer == 0) {
        oled_timer = timer_read();
    }

    if (is_oled_on() && (timer_elapsed(oled_timer) < 20000)) {
        render_anim();
        render_mod_status(get_mods());
        led_t led_state = host_keyboard_led_state();
        oled_set_cursor(0,1);
        oled_write_P(led_state.caps_lock ? PSTR("CAPS") : PSTR("    "), false);
        oled_set_cursor(0,2);
        oled_write_P(led_state.num_lock ? PSTR("NUM") : PSTR("    "), false);
        oled_set_cursor(15,3);
        switch (get_highest_layer(layer_state)) {  
            case 0:
                oled_write_P(PSTR("  Base"), false); 
                break;
            case 1:
                oled_write_P(PSTR(" Lower"), false);
                break;
            case 2:
                oled_write_P(PSTR(" Raise"), false);
                break;
            case 3:
                oled_write_P(PSTR("Adjust"), false);
                break;
        }
    }
    else if (is_oled_on()) {
        oled_off();
    }
}
